public void enableLineSalesQtyFields(SalesLine _salesLine, boolean _enableUnit, boolean _enableInvent)
{
    next enableLineSalesQtyFields(_salesLine, _enableUnit, _enableInvent);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance())
        && _salesLine.IsFreeItemLine)
    {
        enableDSField(FormDataUtil::getFormDataSource(_salesLine), fieldNum(SalesLine, SalesQty), false);
        enableDSField(FormDataUtil::getFormDataSource(_salesLine), fieldNum(SalesLine, SalesPrice), false);
        enableDSField(FormDataUtil::getFormDataSource(_salesLine), fieldNum(SalesLine, LineAmount), false);

        enableDSField(FormDataUtil::getFormDataSource(_salesLine), fieldNum(SalesLine, SalesPrice), false);
        enableDSField(FormDataUtil::getFormDataSource(_salesLine), fieldNum(SalesLine, PriceUnit), false);
        enableDSField(FormDataUtil::getFormDataSource(_salesLine), fieldNum(SalesLine, LineAmount), false);
        enableDSField(FormDataUtil::getFormDataSource(_salesLine), fieldNum(SalesLine, SalesMarkup), false);
        enableDSField(FormDataUtil::getFormDataSource(_salesLine), fieldNum(SalesLine, LineDisc), false);
        enableDSField(FormDataUtil::getFormDataSource(_salesLine), fieldNum(SalesLine, LinePercent), false);
        enableDSField(FormDataUtil::getFormDataSource(_salesLine), fieldNum(SalesLine, MultiLnDisc), false);
        enableDSField(FormDataUtil::getFormDataSource(_salesLine), fieldNum(SalesLine, MultiLnPercent), false);

        GUPFreeItemLine gupFreeItemLine = GUPFreeItemLine::find( _salesLine.GUPFreeItemLineRecId);
        FormDataUtil::getFormDataSource(_salesLine).object(fieldNum(SalesLine, RetailVariantId)).allowEdit(!gupFreeItemLine.Variant);
    }
}
